"""The 'record' input format: a .txt file written by `plan.py sync-sheets`
from a Google Sheets tab, one block per sheet row, so that git diffs show
exactly which cells changed.

    # GENERATED by `plan.py sync-sheets` ... (comment lines)
    HEADER:type=record
    HEADER:title=Dhatu notes
    HEADER:keys=Words              the column with the lookup keys (';'-separated)
    HEADER:entry=Entry             the column with the entry

    .--- कृ;करोति                   record marker: '.--- ' + the keys cell (for reading only)
    .Added: 2026                   '.<column>: <value>', in the sheet's column order
    .Words: कृ;करोति
    .Entry: to **do**
    a second line of the same cell (lines after the first are written as they are)

Empty cells are left out. A line starting with '.' is always a marker or
a field, so a line in a cell (after its first line) can't start with '.';
the sync refuses such a sheet, naming the row and column. Column names
can't contain ':' or start with '-'.

Only the keys and entry columns go into the dictionary; the others are
kept so the file mirrors the sheet. A record with an empty keys cell is
skipped; keys without an entry is an error, and so is a spreadsheet error
value (#N/A, #REF!, ...) in either column. Line breaks in the entry
become <br>, **bold** works, and the keys are shown at the end of the
entry, as in notes.

The sheet's layout: row 1 is metadata as key/value pairs (keys, entry -
required, the column names; title, lang - as HEADER:title/lang), row 2
the column headers, data from row 3.
"""
import re

import markup
import utils
from errors import DictionaryBuildError
from input_handlers import BaseInputHandler

MARKER = ".---"
FIELD_RE = re.compile(r"^\.([^\s:\-][^:]*): (.*)$")
RECORD_HEADERS = {"type", "title", "lang", "keys", "entry"}
META_KEYS = {"title", "lang", "keys", "entry"}
REQUIRED_META = ("keys", "entry")
# Values Google Sheets shows for a formula error.
SHEET_ERROR_RE = re.compile(r"^#(N/A|REF!|VALUE!|NAME\?|DIV/0!|NUM!|NULL!|ERROR!|SPILL!|CALC!)$")
MAX_REPORTED = 20


# --- sheet rows -> record text (the sync) ---------------------------------

def column_letter(i: int) -> str:
    """0 -> A, 25 -> Z, 26 -> AA."""
    s = ""
    i += 1
    while i:
        i, r = divmod(i - 1, 26)
        s = chr(65 + r) + s
    return s


def parse_meta_row(row: list) -> dict:
    """Row 1 of the sheet: key/value pairs."""
    cells = [c.strip() for c in row]
    while cells and not cells[-1]:
        cells.pop()
    if len(cells) % 2:
        cells.append("")
    meta = {}
    for i in range(0, len(cells), 2):
        key, value = cells[i], cells[i + 1]
        if not key and not value:
            continue
        where = f"row 1 (metadata), column {column_letter(i)}"
        if not key:
            raise DictionaryBuildError(
                f"row 1 (metadata): value {value!r} has no key in the cell before it")
        if key not in META_KEYS:
            raise DictionaryBuildError(
                f"{where}: unsupported key {key!r} (expected key/value pairs, keys from "
                f"{sorted(META_KEYS)}; row 1 must be metadata, row 2 the column headers)")
        if key in meta:
            raise DictionaryBuildError(f"row 1 (metadata): {key!r} given twice")
        if not value:
            raise DictionaryBuildError(f"row 1 (metadata): no value for {key!r}")
        if "\n" in value:
            raise DictionaryBuildError(f"row 1 (metadata): {key!r} has a line break")
        meta[key] = value
    missing = [k for k in REQUIRED_META if k not in meta]
    if missing:
        raise DictionaryBuildError(
            f"row 1 (metadata): missing {', '.join(repr(k) for k in missing)} "
            "(the names of the key and entry columns)")
    return meta


def check_record(cells: dict, keys_col: str, entry_col: str):
    """-> None (no keys: skip) or (keys, raw entry). Raises
    DictionaryBuildError (no location) for a bad record."""
    for col in (keys_col, entry_col):
        value = cells.get(col, "")
        if SHEET_ERROR_RE.match(value):
            raise DictionaryBuildError(
                f"column {col!r} shows a spreadsheet error {value!r}")
    keys = [k.strip() for k in cells.get(keys_col, "").split(";") if k.strip()]
    if not keys:
        return None
    entry = cells.get(entry_col, "")
    if not entry:
        raise DictionaryBuildError(
            f"no entry ({entry_col!r}) for keys {cells.get(keys_col)!r}")
    return keys, entry


def _columns(header: list, data: list) -> list:
    """-> [(index, name)] of the named columns; checks the names."""
    problems, cols, seen = [], [], set()
    for j, name in enumerate(header):
        where = f"row 2, column {column_letter(j)}"
        if not name:
            if any(j < len(r) and r[j] for r in data):
                problems.append(f"{where}: the column has data but no name")
            continue
        if ":" in name or name.startswith("-") or "\n" in name:
            problems.append(f"{where}: column name {name!r} can't contain ':' or a line "
                            "break, or start with '-'")
        elif name in seen:
            problems.append(f"{where}: column name {name!r} used twice")
        seen.add(name)
        cols.append((j, name))
    if problems:
        raise DictionaryBuildError("; ".join(problems))
    return cols


def rows_to_text(rows: list, comments: list = ()) -> str:
    """Tidied sheet rows -> the record file's text. Every problem in the
    data rows is reported (up to MAX_REPORTED), by sheet row and column."""
    if not rows or not any(any(r) for r in rows):
        raise DictionaryBuildError("the tab is empty")
    meta = parse_meta_row(rows[0])
    if len(rows) < 2:
        raise DictionaryBuildError("no column header row (row 2)")
    header, data = rows[1], rows[2:]
    cols = _columns(header, data)
    names = [n for _, n in cols]
    for what in REQUIRED_META:
        if meta[what] not in names:
            raise DictionaryBuildError(
                f"row 2: no column {meta[what]!r} (named by {what!r} in row 1); "
                f"columns are {names}")

    out = [f"# {c}" for c in comments]
    out.append("HEADER:type=record")
    for k in ("title", "lang", "keys", "entry"):
        if k in meta:
            out.append(f"HEADER:{k}={meta[k]}")

    problems = []
    for i, row in enumerate(data, start=3):
        cells = {n: row[j] for j, n in cols if j < len(row) and row[j]}
        if not cells:
            continue
        for j, n in cols:
            for k, line in enumerate(cells.get(n, "").split("\n")[1:], start=2):
                if line.startswith("."):
                    problems.append(
                        f"row {i}, column {column_letter(j)} ({n}): line {k} of the cell "
                        "starts with '.' (not allowed after a cell's first line)")
        try:
            rec = check_record(cells, meta["keys"], meta["entry"])
            if rec:
                markup.apply_bold_markup(rec[1])
        except DictionaryBuildError as e:
            problems.append(f"row {i}: {e.message}")
        out.append("")
        out.append(f"{MARKER} {' '.join(cells.get(meta['keys'], '').split())}".rstrip())
        for _, n in cols:
            if n in cells:
                first, *rest = cells[n].split("\n")
                out.append(f".{n}: {first}")
                out.extend(rest)
    if problems:
        more = len(problems) - MAX_REPORTED
        shown = problems[:MAX_REPORTED] + ([f"... and {more} more"] if more > 0 else [])
        raise DictionaryBuildError("\n    ".join(["problems in the sheet:"] + shown))
    return "\n".join(out) + "\n"


# --- record text -> records (the build) ------------------------------------

def parse_records(text: str, first_line: int = 1, filename=None) -> list:
    """The records after the HEADER: block. `first_line` is the file line
    `text` starts on. -> [{'line', 'cells': {column: value}, 'lines':
    {column: file line of its first line}}]."""
    records, rec, field = [], None, None

    def err(msg, n):
        return DictionaryBuildError(msg, file=filename, line=n)

    for n, line in enumerate(text.split("\n"), start=first_line):
        if line == MARKER or line.startswith(MARKER + " "):
            rec, field = {"line": n, "cells": {}, "lines": {}}, None
            records.append(rec)
        elif line.startswith("."):
            m = FIELD_RE.match(line)
            if not m:
                raise err(f"bad line {line!r}: a line starting with '.' must be a "
                          f"'{MARKER} ...' record marker or a '.Column: value' field", n)
            if rec is None:
                raise err(f"field before the first '{MARKER}' record marker", n)
            field = m.group(1)
            if field in rec["cells"]:
                raise err(f"column {field!r} given twice in one record", n)
            rec["cells"][field] = [m.group(2)]
            rec["lines"][field] = n
        elif field is not None:
            rec["cells"][field].append(line)
        elif line.strip():
            raise err(f"text outside a field (expected '{MARKER} ...' or '.Column: value')", n)
    for r in records:
        r["cells"] = {k: "\n".join(v).rstrip() for k, v in r["cells"].items()}
    return records


class RecordInputHandler(BaseInputHandler):
    """Like notes and one-liner, keys are used as given (no exclusions)
    and shown at the end of the entry."""

    def __init__(self, translator=None, exclusion_list=None, info=None):
        super().__init__(translator, exclusion_list=[], info=info)

    def extract_record_parts(self, headers: dict, record) -> tuple:
        keys, entry = record
        return list(keys), entry.replace("\n", "<br>")

    def process_text(self, text: str, headers: dict, line_offset: int = 0) -> list:
        """`text`: the file after its HEADER: block (line_offset lines)."""
        bad = set(headers) - RECORD_HEADERS
        if bad:
            raise DictionaryBuildError(
                f"HEADER:{sorted(bad)[0]} is not supported in a record file "
                f"(supported: {sorted(RECORD_HEADERS)})", file=self.filename, line=1)
        for k in REQUIRED_META:
            if not headers.get(k, "").strip():
                raise DictionaryBuildError(
                    f"a record file needs HEADER:{k}= (the {k} column's name)",
                    file=self.filename, line=1)
        keys_col, entry_col = headers["keys"].strip(), headers["entry"].strip()
        records = []
        for rec in parse_records(text, line_offset + 1, self.filename):
            try:
                parts = check_record(rec["cells"], keys_col, entry_col)
            except DictionaryBuildError as e:
                raise e.with_location(file=self.filename, line=rec["line"])
            if not parts:
                continue
            keys, entry = parts
            entry = markup.apply_bold_markup(entry, filename=self.filename,
                                             line_offset=rec["lines"][entry_col] - 1)
            records.append((rec["line"], (keys, entry)))
        return self.process_records(records, headers)


def read_record_file(path, text: str, translator) -> list:
    """Parses a whole record file (`text`, `path` for messages) as the
    build does. -> entries."""
    try:
        headers, rest, n = utils.read_header(text.strip().replace("\r", ""),
                                             allowed_tags=RECORD_HEADERS)
    except DictionaryBuildError as e:
        raise e.with_location(file=path)
    if headers.get("type", "").strip() != "record":
        raise DictionaryBuildError("not a record file (no HEADER:type=record)", file=path, line=1)
    return RecordInputHandler(translator, info=str(path)).process_text(rest, headers, n)
